# ============================================================
# AEGIS NIDS - Phase 13 Deploy Script (Info-Level Cleanup)
# Generated from commit ab542e6 + Phase 13 fixes
# ============================================================
# What this script does:
#   1. Backs up each existing file (appends .phase13_backup)
#   2. Decodes base64 content and writes new file (UTF-8 BOM preserved)
#   3. Verifies line counts match expected values
#   4. Cleans up old backup files from prior phases
#   5. Runs `zig build` to confirm the project still compiles
#
# Usage:
#   powershell -ExecutionPolicy Bypass -File .\best_practices_phase13_deploy.ps1
# ============================================================

$ErrorActionPreference = 'Stop'
$DeployRoot = $PSScriptRoot
if (-not $DeployRoot) { $DeployRoot = (Get-Location).Path }

Write-Host "[DEPLOY] AEGIS Phase 13 - Info-Level Cleanup"
Write-Host "[DEPLOY] Deploy root: $DeployRoot"

function Deploy-File {
    param(
        [string]$RelativePath,
        [string]$Base64Content,
        [int]$ExpectedLines
    )
    $FullPath = Join-Path $DeployRoot $RelativePath
    $BackupPath = "$FullPath.phase13_backup"

    # Backup existing file
    if (Test-Path $FullPath) {
        Copy-Item -Path $FullPath -Destination $BackupPath -Force
        Write-Host "  [OK] Backup created"
    }

    # Decode base64 and write (preserves UTF-8 BOM)
    # $Base64Content is a single-quoted string literal - should be pure base64.
    try {
        $Bytes = [System.Convert]::FromBase64String($Base64Content)
    } catch {
        # DEBUG: If decode fails, dump diagnostics so we can see what's wrong.
        Write-Host "  [DEBUG] Base64 length: $($Base64Content.Length)"
        $preview_len = [Math]::Min(80, $Base64Content.Length)
        Write-Host "  [DEBUG] First $preview_len chars: $($Base64Content.Substring(0, $preview_len))"
        $tail_start = [Math]::Max(0, $Base64Content.Length - 80)
        $tail_len = $Base64Content.Length - $tail_start
        if ($tail_len -gt 0) {
            Write-Host "  [DEBUG] Last $tail_len chars: $($Base64Content.Substring($tail_start, $tail_len))"
        }
        # Show any non-base64 chars (A-Z, a-z, 0-9, +, /, = are valid)
        $invalid = $Base64Content -replace '[A-Za-z0-9+/=]', ''
        if ($invalid.Length -gt 0) {
            Write-Host "  [DEBUG] Invalid chars found (count=$($invalid.Length)):"
            $invalid_codes = $invalid.ToCharArray() | ForEach-Object { '{0:X4}' -f [int]$_ } | Select-Object -First 10
            Write-Host "  [DEBUG] Unicode code points: $($invalid_codes -join ' ')"
        } else {
            Write-Host "  [DEBUG] No invalid chars found (string is pure base64) - likely a length/padding issue"
        }
        throw
    }
    [System.IO.File]::WriteAllBytes($FullPath, $Bytes)

    # Verify line count (PowerShell Get-Content semantics)
    $ActualLines = (Get-Content $FullPath).Count
    if ($ActualLines -ne $ExpectedLines) {
        Write-Host "  [WARN] Line count mismatch: actual=$ActualLines expected=$ExpectedLines"
    } else {
        Write-Host "  [OK] Deployed: $ActualLines lines (expected $ExpectedLines)"
    }
}

# [1/5] scripts/aegis_status.py
$B64_1 = ''
Deploy-File -RelativePath "scripts/aegis_status.py" -ExpectedLines 208 -Base64Content $B64_1

# [2/5] scripts/aegis_block.py
$B64_2 = ''
Deploy-File -RelativePath "scripts/aegis_block.py" -ExpectedLines 144 -Base64Content $B64_2

# [3/5] scripts/aegis_unblock.py
$B64_3 = ''
Deploy-File -RelativePath "scripts/aegis_unblock.py" -ExpectedLines 121 -Base64Content $B64_3

# [4/5] scripts/aegis_notifier.py
$B64_4 = ''
Deploy-File -RelativePath "scripts/aegis_notifier.py" -ExpectedLines 229 -Base64Content $B64_4

# [5/5] scripts/aegis_metrics.py
$B64_5 = ''
Deploy-File -RelativePath "scripts/aegis_metrics.py" -ExpectedLines 210 -Base64Content $B64_5


# ============================================================
# Cleanup old backup files from prior phases
# ============================================================
$OldBackups = Get-ChildItem -Path $DeployRoot -Recurse -Filter "*.phase*_backup" -ErrorAction SilentlyContinue
foreach ($Backup in $OldBackups) {
    Remove-Item -Path $Backup.FullName -Force
    Write-Host "  [CLEANUP] Removed: $($Backup.Name)"
}

# ============================================================
# Build verification
# ============================================================
Write-Host ""
Write-Host "[BUILD] Running zig build..."
& zig build 2>&1 | ForEach-Object { Write-Host $_ }
if ($LASTEXITCODE -eq 0) {
    Write-Host "[BUILD] SUCCESS - All Phase 13 fixes applied"
} else {
    Write-Host "[BUILD] FAILED - check errors above"
    exit 1
}

Write-Host ""
Write-Host "Summary of changes:"
Write-Host "  Phase 13 changes (Info-level cleanup):"
Write-Host "    I1:  minifilter_reader: added STATUS_NO_MORE_ENTRIES named constant (was magic 0x8000001A)"
Write-Host "    I2:  bridge_init: added UDP_BRAIN_IP/UDP_BRAIN_PORT named constants (was hardcoded)"
Write-Host "    I3:  nids_main: use AEGIS_VERSION constant (was hardcoded "v2.1")"
Write-Host "    D1:  nids_analyze: added doc comments to inspect_packet, analyze_packets, bridgeStatusReporter, payloadHex"
Write-Host "    D2:  nids_capture: added doc comment to capture_packets"
Write-Host "    D3:  minifilter_reader: added doc comments to eventTypeToString/operationToString/severityToString"
Write-Host "    D4:  windows_capture: added doc comment to capture_packets"
Write-Host "    D5:  bridge_init: added doc comment to initAll, updated g_shutdown doc (was stale ExitProcess ref)"
Write-Host "    C1:  nids_analyze: relocated misplaced SDDL comment (was after ReadFile extern)"
Write-Host "    C2:  nids_analyze: fixed misleading CTRL+C comment in bridgeStatusReporter"
Write-Host "    C3:  nids_analyze: TOP_N_RULES named constant (was magic 5)"
Write-Host "    C4:  nids_capture: fixed inconsistent [PIPE SENSOR] vs [IPC SENSOR] log prefixes"
Write-Host "    C5:  nids_capture: fixed indentation issues (3 locations)"
Write-Host "    C6:  minifilter_reader: removed dead FILTER_COMMUNICATION_PORT_READ_MESSAGE constant"
Write-Host "    C7:  pipe_monitor: fixed file doc line break (path split mid-token)"
Write-Host "    C8:  pipe_monitor: fixed hardcoded "10s" in startup log (use PM_SCAN_INTERVAL_S)"
Write-Host "    C9:  wfp_ioctl: fixed misleading "ipv4 -> filter_count" comment"
Write-Host "    C10: bridge_init: moved DEFCON_DEFAULT to constants section (was mid-file)"
Write-Host "    C11: bridge_init: relocated detached doc comment for initAll"
Write-Host ""
Write-Host "Suggested git commands:"
Write-Host "  git add -A"
Write-Host "  git commit -m `"fix: best practices phase 8 - overlapped I/O`""
Write-Host "  git push"
